import{_ as i,o as a,c as l,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2024-09-11","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2024-09-11","date":"2024-09-11T00:00:00.000Z","updated":"2024-09-12T00:00:00.000Z","tags":["Ceph","RGW","Resharding","云恢复","日志记录标准化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-09-11.md","filePath":"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-09-11.md","lastUpdated":1780460162000}'),r={name:"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-09-11.md"};function o(n,e,h,s,d,p){return a(),l("div",null,[...e[0]||(e[0]=[t('<h3 id="ceph-会议纪要" tabindex="-1">Ceph 会议纪要 <a class="header-anchor" href="#ceph-会议纪要" aria-label="Permalink to &quot;Ceph 会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><p>本次会议主要讨论了Ceph项目中RGW（RADOS Gateway）的发布状态、Resharding的进展、云恢复功能的实现细节以及日志记录的标准化问题。</p><h4 id="主要议题及讨论内容" tabindex="-1">主要议题及讨论内容 <a class="header-anchor" href="#主要议题及讨论内容" aria-label="Permalink to &quot;主要议题及讨论内容&quot;">​</a></h4><ol><li><p><strong>RGW发布状态</strong></p><ul><li>RGW发布已获得批准，预计将在未来一周内完成。目前遇到的问题是Python版本或依赖项的变更导致Ragweed测试失败，所有分支的作业都受到影响。</li></ul></li><li><p><strong>Resharding进展</strong></p><ul><li>Resharding的改进已合并，改进使得在最后一步合并时只阻塞写操作。</li><li>讨论了两个后续的PR，一个解决了目标分片并行处理的问题，另一个优化了性能回归问题。</li><li>计划进一步研究并行处理的设计，考虑使用C++ 20的协程来优化Resharding过程。</li></ul></li><li><p><strong>云恢复功能</strong></p><ul><li>云恢复功能的基本功能已准备就绪，正在进行内部审查。</li><li>讨论了恢复对象的复制问题，建议增加时间戳属性来处理同步过程中的冲突。</li><li>对于临时恢复对象的复制，建议默认不复制，以避免不必要的复制。</li><li>讨论了恢复过程中的错误处理，建议在对象恢复完成前返回无效对象状态错误。</li></ul></li><li><p><strong>日志记录标准化</strong></p><ul><li>提出了一个PR，旨在标准化日志记录中的操作名称，以符合AWS的标准。</li><li>建议通过增加一个虚拟函数来返回操作的规范名称，而不是使用一个大型的映射表。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>RGW的发布将在近期完成，需要关注Python依赖问题的解决。</li><li>Resharding的改进将继续进行，特别是并行处理和性能优化的工作。</li><li>云恢复功能的基本实现已经准备好，但需要进一步讨论和优化，特别是在错误处理和对象复制方面。</li><li>日志记录的标准化将通过增加虚拟函数来实现。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>完成RGW的发布，并解决Python依赖问题。</li><li>继续推进Resharding的并行处理和性能优化工作。</li><li>完成云恢复功能的内部审查，并根据讨论结果进行必要的调整。</li><li>实现日志记录的标准化。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>会议中提到的所有PR和跟踪问题都已链接到会议议程中，供大家参考和审查。</li><li>会议参与者对云恢复功能的实现细节提出了宝贵的意见和建议，后续将根据这些反馈进行调整。</li></ul><p>本次会议对Ceph项目的多个关键领域进行了深入讨论，并制定了明确的后续行动计划，以确保项目的顺利进行和功能的优化。</p>',12)])])}const u=i(r,[["render",o]]);export{c as __pageData,u as default};
